from functools import wraps

def beg(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        msg, say_please = fn(*args, **kwargs)
        return msg + ' Please!' if say_please else msg
    return wrapper

@beg
def say(say_please=False):
    return 'Can you buy me a beer?', say_please
